import type {
  ApplicationAnswer,
  ConsentRecord,
  ConsentStatus,
  CvExtraction,
  ExtractionStatus,
  Outcome,
  PrivacyNotice,
  SubmittedContact,
} from '@candydati/domain';
import { sql } from 'drizzle-orm';
import { boolean, check, customType, index, integer, jsonb, pgTable, text, timestamp, uniqueIndex } from 'drizzle-orm/pg-core';
import { organization } from './auth.js';
import { job } from './job.js';
import { importBatch } from './import.js';
import { migrationBatchRef } from './migration.js';

/** Postgres full-text vector: only ever generated by the database, never written by the application. */
const tsvector = customType<{ data: string }>({ dataType: () => 'tsvector' });

const organizationRef = () =>
  text('organization_id')
    .notNull()
    .references(() => organization.id, { onDelete: 'restrict' });

/**
 * Versioned privacy notice (PRODUCT.md §6). Rows are never updated: a change is a new version, and every application
 * keeps the version it consented to. `version` is unique inside the organization.
 */
export const privacyNotice = pgTable(
  'privacy_notice',
  {
    id: text('id').primaryKey(),
    organizationId: organizationRef(),
    version: integer('version').notNull(),
    language: text('language').$type<PrivacyNotice['language']>().notNull(),
    text: text('text').notNull(),
    contactEmail: text('contact_email').notNull(),
    retentionDays: jsonb('retention_days').$type<PrivacyNotice['retentionDays']>().notNull(),
    createdBy: text('created_by').notNull(),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [uniqueIndex('privacy_notice_org_version_uidx').on(table.organizationId, table.version)],
);

/** One person per organization: the email is unique case-insensitively. */
export const candidate = pgTable(
  'candidate',
  {
    id: text('id').primaryKey(),
    organizationId: organizationRef(),
    firstName: text('first_name').notNull(),
    lastName: text('last_name').notNull(),
    email: text('email').notNull(),
    phone: text('phone'),
    linkedinUrl: text('linkedin_url'),
    tags: text('tags').array().notNull().default(sql`'{}'::text[]`),
    talentPool: boolean('talent_pool').notNull().default(false),
    retentionExpiresAt: timestamp('retention_expires_at', { withTimezone: true }).notNull(),
    /** Set when an import created the candidate. */
    importBatchId: text('import_batch_id').references(() => importBatch.id, { onDelete: 'restrict' }),
    /** Set when a migration created the candidate. */
    migrationBatchId: migrationBatchRef(),
    /** Latest `created_at` of a consented application. Kept by the `application_refresh_candidate_last_applied` trigger. */
    lastAppliedAt: timestamp('last_applied_at', { withTimezone: true }),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [
    uniqueIndex('candidate_org_email_uidx').on(table.organizationId, sql`lower(${table.email})`),
    index('candidate_org_created_at_idx').on(table.organizationId, sql`${table.createdAt} desc`),
    // The list order: most recently applied first, never-applied last.
    index('candidate_org_last_applied_idx').on(table.organizationId, sql`${table.lastAppliedAt} desc nulls last`, table.id),
    // Trigram indexes behind the free-text search (ILIKE '%x%'); `candidate_tags_text` is an immutable wrapper.
    index('candidate_name_trgm_idx').using('gin', sql`(${table.firstName} || ' ' || ${table.lastName}) gin_trgm_ops`),
    index('candidate_email_trgm_idx').using('gin', sql`${table.email} gin_trgm_ops`),
    index('candidate_tags_trgm_idx').using('gin', sql`candidate_tags_text(${table.tags}) gin_trgm_ops`),
    index('candidate_migration_batch_idx').on(table.migrationBatchId).where(sql`${table.migrationBatchId} is not null`),
  ],
);

export const application = pgTable(
  'application',
  {
    id: text('id').primaryKey(),
    organizationId: organizationRef(),
    jobId: text('job_id')
      .notNull()
      .references(() => job.id, { onDelete: 'restrict' }),
    candidateId: text('candidate_id')
      .notNull()
      .references(() => candidate.id, { onDelete: 'restrict' }),
    stageId: text('stage_id').notNull(),
    outcome: text('outcome').$type<Outcome>(),
    message: text('message').notNull().default(''),
    /** The four CV columns are set together; only a migrated application may have none (`application_cv_check`). */
    cvKey: text('cv_key'),
    cvFileName: text('cv_file_name'),
    cvMediaType: text('cv_media_type'),
    cvSizeBytes: integer('cv_size_bytes'),
    /** Form answers kept from the source ATS of a migration: an array of {question, answer}, capped (`application_answers_check`). */
    answers: jsonb('answers').$type<readonly ApplicationAnswer[]>(),
    /** Contact data typed on the public form, kept apart from the candidate profile for a recruiter to review. */
    submittedContact: jsonb('submitted_contact').$type<SubmittedContact>(),
    consent: jsonb('consent').$type<ConsentRecord>().notNull(),
    /** `to_renew` for imported data until the candidate reconfirms. Existing rows are `given`. */
    consentStatus: text('consent_status').$type<ConsentStatus>().notNull().default('given'),
    importBatchId: text('import_batch_id').references(() => importBatch.id, { onDelete: 'restrict' }),
    /** The migration that created this application, with its original dates and outcome. */
    migrationBatchId: migrationBatchRef(),
    retentionExpiresAt: timestamp('retention_expires_at', { withTimezone: true }).notNull(),
    source: text('source').$type<'careers_page' | 'manual' | 'import'>().notNull(),
    /** Sanitized label of where the application came from; `direct` when unknown. */
    origin: text('origin').notNull().default('direct'),
    /** Sanitized `utm_campaign` of the ad URL; null when there was none. */
    originCampaign: text('origin_campaign'),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).defaultNow().notNull(),
    stageChangedAt: timestamp('stage_changed_at', { withTimezone: true }).defaultNow().notNull(),
    closedAt: timestamp('closed_at', { withTimezone: true }),
    /** Deadline of the promise to answer; null once answered or decided. */
    responseDueAt: timestamp('response_due_at', { withTimezone: true }),
    respondedAt: timestamp('responded_at', { withTimezone: true }),
    /** Imported data: when the reconfirmation email actually went out. Retention never erases someone never asked. */
    reconfirmationSentAt: timestamp('reconfirmation_sent_at', { withTimezone: true }),
  },
  (table) => [
    // A candidate cannot have two OPEN applications to the same job; a decided one does not block a new one.
    uniqueIndex('application_job_candidate_open_uidx')
      .on(table.jobId, table.candidateId)
      .where(sql`${table.outcome} is null`),
    index('application_org_job_idx').on(table.organizationId, table.jobId),
    index('application_org_candidate_idx').on(table.organizationId, table.candidateId),
    index('application_import_batch_idx').on(table.importBatchId),
    // Daily caps of the public form count recent careers-page applications.
    index('application_careers_created_idx')
      .on(table.organizationId, table.createdAt)
      .where(sql`${table.source} = 'careers_page'`),
    // Retention scan, keyset ordered by (retention_expires_at, id).
    index('application_retention_idx').on(table.retentionExpiresAt, table.id),
    // Backs the deadline scan and the attention list: only open applications still waiting for an answer.
    index('application_awaiting_response_idx')
      .on(table.organizationId, table.responseDueAt)
      .where(sql`${table.outcome} is null and ${table.responseDueAt} is not null`),
    index('application_migration_batch_idx').on(table.migrationBatchId).where(sql`${table.migrationBatchId} is not null`),
    // ANSWERS_MAX_BYTES of @candydati/domain; a test keeps the two equal.
    check(
      'application_answers_check',
      sql`${table.answers} is null or (jsonb_typeof(${table.answers}) = 'array' and octet_length(${table.answers}::text) <= 1048576)`,
    ),
    check(
      'application_cv_check',
      sql`(${table.cvKey} is not null and ${table.cvFileName} is not null and ${table.cvMediaType} is not null and ${table.cvSizeBytes} is not null) or (${table.migrationBatchId} is not null and ${table.cvKey} is null and ${table.cvFileName} is null and ${table.cvMediaType} is null and ${table.cvSizeBytes} is null)`,
    ),
  ],
);

export const candidateNote = pgTable(
  'candidate_note',
  {
    id: text('id').primaryKey(),
    organizationId: organizationRef(),
    candidateId: text('candidate_id')
      .notNull()
      .references(() => candidate.id, { onDelete: 'restrict' }),
    applicationId: text('application_id').references(() => application.id, { onDelete: 'restrict' }),
    /** Plain text with no foreign key: notes survive the removal of the user who wrote them. Null for an external author. */
    authorId: text('author_id'),
    /** Who wrote a migrated note when they are not a member here (the previous ATS's user). */
    authorName: text('author_name'),
    body: text('body').notNull(),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
    migrationBatchId: migrationBatchRef(),
  },
  (table) => [
    index('candidate_note_org_candidate_idx').on(table.organizationId, table.candidateId),
    index('candidate_note_migration_batch_idx').on(table.migrationBatchId).where(sql`${table.migrationBatchId} is not null`),
    check('candidate_note_author_check', sql`${table.authorId} is not null or coalesce(length(btrim(${table.authorName})), 0) > 0`),
  ],
);

/** `search` is generated by Postgres from `text` and backs full-text search over CVs. */
export const cvExtraction = pgTable(
  'cv_extraction',
  {
    applicationId: text('application_id')
      .primaryKey()
      .references(() => application.id, { onDelete: 'cascade' }),
    organizationId: organizationRef(),
    status: text('status').$type<ExtractionStatus>().notNull(),
    text: text('text'),
    data: jsonb('data').$type<CvExtraction>(),
    source: text('source').$type<'model' | 'text'>(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).defaultNow().notNull(),
    search: tsvector('search').generatedAlwaysAs(sql`to_tsvector('simple', coalesce(text, ''))`),
  },
  (table) => [
    index('cv_extraction_search_idx').using('gin', table.search),
    index('cv_extraction_org_idx').on(table.organizationId),
  ],
);

export type PrivacyNoticeRow = typeof privacyNotice.$inferSelect;
export type CandidateRow = typeof candidate.$inferSelect;
export type ApplicationRow = typeof application.$inferSelect;
export type CandidateNoteRow = typeof candidateNote.$inferSelect;
/**
 * Reconfirmation link of an imported application. Only the hash of the token is stored; the token is single-use and
 * expires with the data it protects (`expires_at` = the application's retention expiry).
 */
export const consentToken = pgTable(
  'consent_token',
  {
    tokenHash: text('token_hash').primaryKey(),
    organizationId: organizationRef(),
    applicationId: text('application_id')
      .notNull()
      .references(() => application.id, { onDelete: 'restrict' }),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    usedAt: timestamp('used_at', { withTimezone: true }),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [index('consent_token_application_idx').on(table.applicationId)],
);

export type ConsentTokenRow = typeof consentToken.$inferSelect;
export type CvExtractionRow = typeof cvExtraction.$inferSelect;
